package com.procurement.vendorquotation.entity;
import com.procurement.rfq.entity.Rfq;import com.procurement.vendor.entity.Vendor;import jakarta.persistence.*;import lombok.*;import java.math.BigDecimal;import java.time.*;
@Entity @Table(name="vendor_quotations",uniqueConstraints={@UniqueConstraint(columnNames="quotation_number"),@UniqueConstraint(columnNames={"rfq_id","vendor_id"})}) @Getter @Setter @NoArgsConstructor @AllArgsConstructor @Builder public class VendorQuotation{ @Id @GeneratedValue(strategy=GenerationType.IDENTITY)@Column(name="vendor_quotation_id")private Long id;@Column(name="quotation_number",nullable=false,length=40)private String quotationNumber;@ManyToOne(fetch=FetchType.LAZY,optional=false)@JoinColumn(name="rfq_id",nullable=false)private Rfq rfq;@ManyToOne(fetch=FetchType.LAZY,optional=false)@JoinColumn(name="vendor_id",nullable=false)private Vendor vendor;@Column(name="submission_date")private LocalDate submissionDate;@Column(name="valid_until")private LocalDate validUntil;@Column(nullable=false,length=3)private String currency;@Column(nullable=false,precision=15,scale=2)@Builder.Default private BigDecimal subtotal=BigDecimal.ZERO;@Column(name="discount_amount",nullable=false,precision=15,scale=2)@Builder.Default private BigDecimal discountAmount=BigDecimal.ZERO;@Column(name="tax_amount",nullable=false,precision=15,scale=2)@Builder.Default private BigDecimal taxAmount=BigDecimal.ZERO;@Column(name="shipping_charges",nullable=false,precision=15,scale=2)@Builder.Default private BigDecimal shippingCharges=BigDecimal.ZERO;@Column(name="other_charges",nullable=false,precision=15,scale=2)@Builder.Default private BigDecimal otherCharges=BigDecimal.ZERO;@Column(name="grand_total",nullable=false,precision=15,scale=2)@Builder.Default private BigDecimal grandTotal=BigDecimal.ZERO;@Column(name="payment_terms",length=200)private String paymentTerms;@Column(name="delivery_days")private Integer deliveryDays;@Column(name="delivery_location",length=255)private String deliveryLocation;@Column(name="warranty_months")private Integer warrantyMonths;@Column(length=1000)private String remarks;@Enumerated(EnumType.STRING)@Column(nullable=false,length=20)private VendorQuotationStatus status;@Column(name="created_by",nullable=false,length=100)private String createdBy;@Column(name="updated_by",length=100)private String updatedBy;@Column(name="created_at",updatable=false)private LocalDateTime createdAt;@Column(name="updated_at")private LocalDateTime updatedAt;@PrePersist void pre(){var n=LocalDateTime.now();createdAt=n;updatedAt=n;if(status==null)status=VendorQuotationStatus.DRAFT;}@PreUpdate void upd(){updatedAt=LocalDateTime.now();}}
